# Input: get_questionnaire_data (dataframe) - raw EQ-5D-5L Questionnaire fhir resource (_raw column)
# Output: result (dict) - {linkId: observation/measurement_concept_id}, resolved from each item's SNOMED
#         coding against the CDM's own concept table. No FHIR extensions are used - the Questionnaire's
#         item.code[] SNOMED codes are the only source of truth, matching resolve_person_and_concept_id
#         in the EQ-5d-5l - Meas pipeline.

import json as _json


def _unwrap_input_value(value):
    return value.result if hasattr(value, "result") else value


def _extract_link_id_snomed_codes(questionnaire_raw):
    """{linkId: snomed concept_code} for every Questionnaire item that declares a SNOMED coding."""
    codes = {}
    for item in questionnaire_raw.get("item", []) or []:
        link_id = item.get("linkId")
        if not link_id:
            continue
        for coding in item.get("code", []) or []:
            if coding.get("system") == "http://snomed.info/sct" and coding.get("code"):
                codes[link_id] = coding["code"]
                break
    return codes


def _resolve_snomed_to_concept_ids(snomed_codes, database_code, schema_name):
    """SNOMED concept_code -> standard OMOP concept_id, direct match against the CDM's own concept
    table (vocabulary_id='SNOMED', standard_concept='S')."""
    if not snomed_codes:
        return {}
    dao = DBDao(database_code=database_code)
    escaped_schema = schema_name.replace('"', '""')
    codes_list = "', '".join(c.replace("'", "''") for c in snomed_codes)
    query = f"""
        SELECT concept_code, concept_id
        FROM "{escaped_schema}"."concept"
        WHERE vocabulary_id = 'SNOMED'
          AND standard_concept = 'S'
          AND concept_code IN ('{codes_list}')
    """
    rows = dao.execute_sql(query, fetch=True) or []
    result = {code: int(concept_id) for code, concept_id in rows}
    missing = snomed_codes - result.keys()
    if missing:
        print(f"[build_concept_lookup] no standard SNOMED concept found for codes: {sorted(missing)}")
    return result


def exec(myinput):
    data = _unwrap_input_value(myinput.get("get_questionnaire_data"))

    if data is None or data.empty:
        raise ValueError("No EQ-5D-5L Questionnaire found - load EQ-5D-5LQuestionnaire.json before running this pipeline")

    questionnaire = _json.loads(data.iloc[0]["_raw"])
    link_id_to_snomed = _extract_link_id_snomed_codes(questionnaire)
    print(f"[build_concept_lookup] SNOMED codes by linkId: {link_id_to_snomed}")

    snomed_to_concept_id = _resolve_snomed_to_concept_ids(set(link_id_to_snomed.values()), dest_db, dest_schema)
    lookup = {
        link_id: snomed_to_concept_id[code]
        for link_id, code in link_id_to_snomed.items()
        if code in snomed_to_concept_id
    }

    print(f"[build_concept_lookup] resolved concept_id for {len(lookup)} linkId(s): {lookup}")
    return lookup

